sec("9. SECOND-PASS ROWS (the printed numbers, the wording and the defaults)");
{
    const au = mkAu({ x02_26012: 0.05, s02_26011: -0.03 }); for (const c of ["dark", "lit"]) au[c].x02_26012.forEach((r) => { r.watts += 1000; }); const bl = X.bottomLines(au), f4 = (x) => (x >= 0 ? "+" : "") + x.toFixed(4), pm = (a, b) => f4(X.penPair(au, a, b, 0.02).mean);
    ok("!! the printed numbers are the readings: the gain line gives each arm's gain at 0.005 / 0.02 / 0.04 with its sign (x02_26012, drawing 1000 W more so that the price shows), the unpenalised gain too, the PAIRED line gives the pruned champion against c02, q02, s02_26011 and the random champion in that order, each x02 against c02 and each against its own twin and each y02 against its own twin, and the mean thrust of an arm is 0.30", (() => { const g = [0.005, 0.02, 0.04].map((p) => f4(X.penGainAt(au, "x02_26012", p))), pr = bl[11]; const order = ["c02", "q02", "s02_26011", "y02_26012"].map((q) => pr.indexOf(`x02_26012 minus ${q} at 0.02 `)); return new Set(g).size === 3 && bl[10].includes(`x02_26012 ${g.join(" / ")}`) && bl[13].includes(`x02_26012 ${[0.005, 0.02, 0.04].map((p) => f4(X.unpenGainAt(au, "x02_26012", p))).join(" / ")}`) && order.every((i, k) => i > 0 && (k === 0 || i > order[k - 1])) && pr.includes(`x02_26012 minus c02 at 0.02 ${pm("x02_26012", "c02")}`) && pr.includes(`x02_26012 minus s02_26012 at 0.02 ${pm("x02_26012", "s02_26012")}`) && pr.includes(`y02_26014 minus s02_26014 at 0.02 ${pm("y02_26014", "s02_26014")}`) && pr.startsWith("PAIRED (penalised priced score at 0.02): x02_26012 minus c02 at 0.02 ") && /thrust 0\.30/.test(bl[7]) && X.report(au).some((l) => l.startsWith("  x02_26012  ") && l.endsWith(g.join(" / "))); })());
    ok("!! each SEARCH line names its group and every seed in seed order with its start value and four checkpoints and its lost flights; the CHAMPIONS line each group's checkpoints, both champion arms and the audit-best of each group; the GAP line both groups and H32's champion", /^SEARCH X02 \(start value, then train \/ held-out penalised value and accepted count at each checkpoint\)/.test(bl[2]) && /26011 \[start 0\.4100; 900: train 0\.9000 held 0\.5000 acc 10; 1200: /.test(bl[2]) && /^SEARCH Y02 \(the same\): 26011 \[start 0\.3100; 900: train 0\.9000 held 0\.4900/.test(bl[3]) && bl[2].includes("(0 lost-flights)") && /X02 900: seed 26012 held 0\.5100, 1200: seed 26012 held 0\.5300, 1500: seed 26012 held 0\.5200, 1800: seed 26012 held 0\.5400; Y02 900: seed 26012 held 0\.5000/.test(bl[5]) && /the champions at 1800 are x02_26012 and y02_26012 \(the best pruned on the audit: x02_26012, the best random: y02_/.test(bl[5]) && /X02 champion 0\.3900 \/ 0\.3700 \/ 0\.3800 \/ 0\.3600 at 900 \/ 1200 \/ 1500 \/ 1800, each seed at 1800 26011 0\.3700, 26012 0\.3600/.test(bl[6]) && /Y02 champion 0\.4000/.test(bl[6]) && /\(H32's champion at 1800 0\.0470\)$/.test(bl[6]));
    ok("!! the REPORTED line gives each search's recovery (start value to the 1800 train value, eight of them), the audit means of all twelve networks in rank order (best first) and the unpenalised gain; the LOST line names every lost run by arm, condition and id and not the autopilot's", (() => { const x = mkAu({ x02_26012: 0.05, s02_26011: -0.03 }); x.dark.x02_26013[7].bad = true; x.lit.s02_26011[3].bad = true; x.dark.autopilot[5].bad = true; x.dark.y02_26011[2].bad = true; const b = X.bottomLines(x); return /recovery \(start value to the 1800 train value\) X02 26011 0\.4100 to 0\.9000; X02 26012/.test(b[13]) && /Y02 26014 0\.3100 to 0\.9000; audit means in rank order/.test(b[13]) && b[13].split(/rank order[^;]*?\) /)[1].split(";")[0].split(", ").length === 12 && /the lost runs: s02_26011 lit k3, x02_26013 dark k7, y02_26011 dark k2$/.test(b[8]) && /LOST \(runs lost of 400\): law0 0, c02 0, q02 0, s02_26011 1, s02_26012 0, s02_26013 0, s02_26014 0, x02_26011 0, x02_26012 0, x02_26013 1, x02_26014 0, y02_26011 1,/.test(b[8]); })());
    ok("!! the check texts carry the registered numbers (the checkpoints 900 to 1800 of the groups' weights, the 17 neurons, the importance rule, the generator seeded 4244, the counts, the 72 train ids, the seeds 26011-26014, H37's last id 38399, H32's 12-iteration proof killed after 6)", (() => { const c = X.checksOf(mkAu()), t = (n) => c.find((r) => r.name.startsWith(n)).text; return /8 network searches \(the four seeds of X02 and of Y02\), each with checkpoints at 900, 1200, 1500 and 1800/.test(t("8 SEARCHES")) && /X02 keeps the 17 neurons of greatest importance in network-Wip \(computed again independently\), Y02 the 17 of the registered draw \(generator seeded 4244, read again independently\)/.test(t("THE TOPOLOGIES")) && /each start carries network-Wip's feature weights, biases, kept edges, output weights and output biases at their own places/.test(t("THE STARTS ARE")) && /on the 72 train ids at 0\.02 gives a finite value and a count of flights that lost a run/.test(t("THE STARTS FLY")) && /exactly its group's start value on the 72 train ids at 0\.02/.test(t("THE FIRST")) && /are 26011-26014/.test(t("THE SEEDS")) && /after H37's audit \(38399\)/.test(t("ID SETS")) && /12 iterations, killed after iteration 6, resumed from the state at 4/.test(t("THE SEARCH IS")) && /s02_26011 to s02_26014 are the weights at 1800/.test(t("THE FOUR S02")) && /\(within 1e-6\)/.test(t("ZERO LAW")) && /0\.65 expected/.test(t("PENALISED")); })());
    ok("!! the tables list the right arms: the means list all 16 (autopilot first), the per-arm gains and the LOST, EXTRA POWER and PRICED GAIN lists leave the autopilot out, law0 prints a +0.0000 gain with its sign, the AUDIT line starts with the autopilot, and the headers say 0.02, 0.005 / 0.02 / 0.04 and lost runs of 400", (() => { const R = X.report(mkAu()), at = R.findIndex((l) => l.startsWith("per arm:")), bl2 = X.bottomLines(mkAu()); return R.slice(R.findIndex((l) => l.startsWith("means")) + 1, at).map((l) => l.trim().split(/\s+/)[0]).join() === X.ARM_IDS.join() && R[at + 1].startsWith("  law0       +0.0000 / +0.0000") && R.slice(at + 1, at + 16).map((l) => l.trim().split(/\s+/)[0]).join() === X.ARM_IDS.slice(1).join() && bl2[8].startsWith("LOST (runs lost of 400): law0 0, c02 0") && bl2[9].startsWith("EXTRA POWER (mean of dark and lit extra kW): c02 ") && bl2[10].includes("PENALISED PRICED GAIN (at 0.005 / 0.02 / 0.04): c02 ") && bl2[7].startsWith("AUDIT (dark / lit mean score, dark mean power, mean dark thrust): autopilot ") && /penalised priced score at 0\.02/.test(R[0]) && R.some((l) => l === "per arm: dark / lit gain over the autopilot, extra power (kW, dark / lit), penalised priced gain at 0.005 / 0.02 / 0.04:") && R.some((l) => l === "means (dark score / lit score; dark mean power kW; lit mean power kW; lost runs of 400):") && R.some((l) => l.startsWith("  autopilot  0.")) && !/unpenalised priced gain autopilot/.test(bl2[13]); })());
}
sec("10. SOURCE");
{
    ok("!! the library reads nothing from disk and starts no process (the command hands in wip and the stored results), builds the pilots with createSubPolicy, registers their kinds with the tank, imports H30's penalty pieces, H28's flight and H32's generator and atomic save, uses the fly circuit's own topology, and its loop draws from the counted generator", !/\bfs\b|node:fs|child_process|fetch\(/.test(code) && /PS\.createSubPolicy\(t\.topo/.test(code) && /flyPen = X32\.flyPen/.test(code) && /generatorAfter\(seed, draws\)/.test(code) && /generatorAfter = X32\.generatorAfter/.test(code) && /saveStateAtomic = X32\.saveStateAtomic/.test(code) && /registerPilotKind/.test(code) && /GFC\.EDGES/.test(code) && /PS\.mulberry\(seed\)/.test(code) && !/Math\.random/.test(code));
}
sec("11. ROWS FROM THE MUTATION PASS (survivors turned into rows)");
{
    const flat = () => ({ score: 0.8, watts: 5000 }), bl = X.bottomLines(mkAu());
    const wip2 = Array.from({ length: 963 }, (_, i) => (i + 1) / 1000);
    ok("!! startOf puts every weight where the layout says, checked against a reference written out in this gate with distinct values (neuron-major first layer, hidden biases, the kept recurrent edges, output-major second layer, output biases; both groups, exact in float32)", [XS, YS].every((sm) => { const K = sm.kept.length, st = X.startOf(wip2, sm.kept, sm.edgeIndex), ref = new Float32Array(14 * K + K + sm.edgeIndex.length + 4 * K + 4); sm.kept.forEach((j, i) => { for (let f = 0; f < 14; f++) ref[i * 14 + f] = wip2[j * 14 + f]; ref[14 * K + i] = wip2[476 + j]; for (let o = 0; o < 4; o++) ref[14 * K + K + sm.edgeIndex.length + o * K + i] = wip2[823 + o * 34 + j]; }); sm.edgeIndex.forEach((k, i) => { ref[14 * K + K + i] = wip2[510 + k]; }); for (let o = 0; o < 4; o++) ref[14 * K + K + sm.edgeIndex.length + 4 * K + o] = wip2[959 + o]; return st.length === ref.length && st.every((v, i) => v === ref[i]); }));
    ok("!! the kinds and policies are labelled for their group (kind 'H38 X02' / 'H38 Y02', policy 'the pruned Giant Fiber Circuit' / 'the random-subset Giant Fiber Circuit', circuits h38-x02 and h38-y02); netObj's DEFAULT group is X02 (an arm of circuit h38-x02) and an explicit Y02 builds h38-y02; a price of 0 is legal (the plain score) and a negative one is refused", XS.kind.label === "H38 X02" && YS.kind.label === "H38 Y02" && XS.policy.name === "the pruned Giant Fiber Circuit" && YS.policy.name === "the random-subset Giant Fiber Circuit" && XS.kind.circuit === "h38-x02" && YS.kind.circuit === "h38-y02" && (() => { const seen = []; const fake = (arm, range) => { seen.push(arm.entry().circuit); return Array.from({ length: range.to - range.from + 1 }, () => ({ key: "k", score: 0.7, bad: false, watts: 5000, thrust: 0 })); }; const a = X.netObj(XS.start, [{ from: 1, to: 1 }], 0, 5, fake), b = X.netObj(YS.start, [{ from: 1, to: 1 }], 0.02, 5, fake, "Y02"); return near(a, 0.7) && near(b, 0.6) && J(seen) === '["h38-x02","h38-x02","h38-y02","h38-y02"]'; })() && /the price must be a number of 0 or more/.test(thr(() => X.netObj(XS.start, [{ from: 1, to: 1 }], -0.01, 5, () => []))));
    ok("!! a flat score (every child ties its parent) is ACCEPTED every iteration in both groups (accepted 6 at iteration 6 and 12 at 12: a child is kept when at least as good); a run lost on ONE id of two in a start flight counts that flight lost (startValues: 2 lost flights per group)", ["X02", "Y02"].every((g) => { const r = run(g, flat); return r.checkpoints[0].accepted === 6 && r.checkpoints[1].accepted === 12; }) && (() => { const v = X.startValues(WIP, { train: [{ from: 1, to: 2 }], seconds: 5, flyFn: (arm, range) => [{ key: "a", score: 0.5, bad: true, watts: 5000, thrust: 0 }, { key: "b", score: 0.5, bad: false, watts: 5000, thrust: 0 }].slice(0, range.to - range.from + 1) }); return v.X02.lost === 2 && v.Y02.lost === 2; })());
    ok("!! every default flight is H28's flyPen (the five defaults in the library: netObj, longSearch, audit, startValues, startVal), read from the source because no small-network candidate crashes the flight", (code.match(/flyFn = flyPen/g) || []).length === 5 && !/flyFn = H15\.fly/.test(code));
    const au2 = mkAu({ y02_26013: 0.05, x02_26011: 0.03 }), rep = X.bottomLines(au2)[13], ranks = rep.match(/at 0\.02\) (.*?); unpenalised/)[1].split(", ").map((t) => t.split(" "));
    const imp = X.importanceOf(WIP), kept = XS.kept, others = Array.from({ length: 34 }, (_, j) => j).filter((j) => !kept.includes(j));
    ok("!! the lines name the right arms and numbers: c02 and q02 once each (c02 first) in the AUDIT, EXTRA POWER and PRICED GAIN lines; the REPORTED line says the price 0.02 and ranks the networks best first (y02_26013 raised: first, x02_26011 second, descending); the TOPOLOGY line gives X02's smallest kept importance and the largest dropped, computed here from wip", /: c02 .*; q02 /.test(bl[9]) && /; q02 /.test(bl[10]) && /; q02 [\d.]+ \/ /.test(bl[7]) && (bl[10].match(/c02 [+-]/g) || []).length === 1 && (bl[10].match(/q02 [+-]/g) || []).length === 1 && /audit means in rank order \(penalised priced score at 0\.02\)/.test(rep) && ranks.length === 12 && ranks[0][0] === "y02_26013" && ranks[1][0] === "x02_26011" && ranks.every((q, i) => i === 0 || Number(ranks[i - 1][1]) >= Number(q[1])) && bl[0].includes(`smallest kept ${Math.min(...kept.map((j) => imp[j])).toFixed(3)}, largest dropped ${Math.max(...others.map((j) => imp[j])).toFixed(3)}`));
    ok("!! THE TOPOLOGIES row goes red for a finite wip whose importance order differs from the stored smaller circuits' (a dropped neuron 11 given output weights of 100 so that it enters the top 17): the row recomputes the pruned set from the wip it is handed", (() => { const w2 = WIP.slice(); for (let o = 0; o < 4; o++) w2[823 + o * 34 + 11] = 100; const x = mkAu({}, { wip: w2 }); return X.checksOf(x).filter((c) => !c.ok).some((c) => c.name.startsWith("THE TOPOLOGIES")); })());
}
